import { UNIVERSE_ROWS, UNIVERSE_AS_OF } from "./universeData.js";

// The tracked stock universe: every S&P 500 and Nasdaq-100 member plus every
// other NYSE or Nasdaq listed stock above $20B, largest first. The rows are
// generated by scripts/build-universe.mjs; this module only shapes them.

export { UNIVERSE_AS_OF };

export const UNIVERSE = UNIVERSE_ROWS.map(([symbol, name, sector, index]) => ({
  symbol,
  name,
  sector,
  spx: index.includes("SPX"),
  ndx: index.includes("NDX"),
}));

export const UNIVERSE_SYMBOLS = UNIVERSE.map((u) => u.symbol);

const BY_SYMBOL = new Map(UNIVERSE.map((u) => [u.symbol, u]));

export function universeEntry(symbol) {
  return BY_SYMBOL.get(String(symbol ?? "").trim().toUpperCase()) || null;
}

export const SECTORS = [...new Set(UNIVERSE.map((u) => u.sector).filter(Boolean))].sort();

// Index filter values for the Screener. "other" is everything in neither index.
export const INDEX_OPTIONS = [
  { value: "spx", label: "S&P 500" },
  { value: "ndx", label: "NASDAQ 100" },
  { value: "other", label: "OTHER" },
];

export function inIndex(row, index) {
  if (!index) return true;
  if (index === "spx") return Boolean(row.spx);
  if (index === "ndx") return Boolean(row.ndx);
  if (index === "other") return !row.spx && !row.ndx;
  return true;
}
